    case GLFW_KEY_T: name = "t"; loc = 0; break;
    case GLFW_KEY_U: name = "u"; loc = 0; break;
    case GLFW_KEY_V: name = "v"; loc = 0; break;
    case GLFW_KEY_W: name = "w"; loc = 0; break;
    case GLFW_KEY_X: name = "x"; loc = 0; break;
    case GLFW_KEY_Y: name = "y"; loc = 0; break;
    case GLFW_KEY_Z: name = "z"; loc = 0; break;
    case GLFW_KEY_0: name = "0"; loc = 0; break;
    case GLFW_KEY_1: name = "1"; loc = 0; break;
    case GLFW_KEY_2: name = "2"; loc = 0; break;
    case GLFW_KEY_3: name = "3"; loc = 0; break;
    case GLFW_KEY_4: name = "4"; loc = 0; break;
    case GLFW_KEY_5: name = "5"; loc = 0; break;
    case GLFW_KEY_6: name = "6"; loc = 0; break;
    case GLFW_KEY_7: name = "7"; loc = 0; break;
    case GLFW_KEY_8: name = "8"; loc = 0; break;
    case GLFW_KEY_9: name = "9"; loc = 0; break;
    case GLFW_KEY_SPACE: name = "space"; loc = 0; break;
    case GLFW_KEY_APOSTROPHE: name = "'"; loc = 0; break;
    case GLFW_KEY_COMMA: name = ","; loc = 0; break;
    case GLFW_KEY_MINUS: name = "-"; loc = 0; break;
    case GLFW_KEY_PERIOD: name = "."; loc = 0; break;
    case GLFW_KEY_SLASH: name = "/"; loc = 0; break;
    case GLFW_KEY_SEMICOLON: name = ";"; loc = 0; break;
    case GLFW_KEY_EQUAL: name = "="; loc = 0; break;
    case GLFW_KEY_LEFT_BRACKET: name = "["; loc = 0; break;
    case GLFW_KEY_BACKSLASH: name = "\\"; loc = 0; break;
