    case GLFW_KEY_F17: name = "f17"; loc = 0; break;
    case GLFW_KEY_F18: name = "f18"; loc = 0; break;
    case GLFW_KEY_F19: name = "f19"; loc = 0; break;
    case GLFW_KEY_F20: name = "f20"; loc = 0; break;
    case GLFW_KEY_F21: name = "f21"; loc = 0; break;
    case GLFW_KEY_F22: name = "f22"; loc = 0; break;
