    case GLFW_KEY_LEFT_SHIFT: name = "shift"; loc = KUI_KLOC_LEFT; break;
    case GLFW_KEY_RIGHT_SHIFT: name = "shift"; loc = KUI_KLOC_RIGHT; break;
    case GLFW_KEY_LEFT_CONTROL: name = "ctrl"; loc = KUI_KLOC_LEFT; break;
    case GLFW_KEY_RIGHT_CONTROL: name = "ctrl"; loc = KUI_KLOC_RIGHT; break;
    case GLFW_KEY_LEFT_ALT: name = "alt"; loc = KUI_KLOC_LEFT; break;
    case GLFW_KEY_RIGHT_ALT: name = "alt"; loc = KUI_KLOC_RIGHT; break;
